verification_commands.ac1:
set -u
export PATH="$HOME/.local/bin:$PATH"
R=security/npm-audit-report.txt
test -f "$R" || { echo "ac1 RED: $R missing"; exit 1; }
command -v make >/dev/null || { echo "ac1 RED: make missing"; exit 1; }
command -v cmd.exe >/dev/null || { echo "ac1 RED: cmd.exe missing"; exit 1; }
python3 - "$R" <<'PYEOF' || exit 1
import re, sys
raw = open(sys.argv[1], "rb").read()
if b"\x00" in raw:
    print("ac1 RED: NUL bytes in the report"); raise SystemExit(1)
t = raw.replace(b"\r", b"").decode("utf-8", "replace")
lines = t.split("\n")
if not lines or lines[0].strip() != "# npm audit report":
    print("ac1 RED: the report no longer leads with '# npm audit report' - the regeneration is not the tool's own output"); raise SystemExit(1)
snap = [i for i, l in enumerate(lines) if "snapshot_date" in l]
if len(snap) != 1:
    print("ac1 RED: %d snapshot_date lines, expected exactly 1 - the dated-snapshot disclosure must exist once and only once" % len(snap)); raise SystemExit(1)
s = lines[snap[0]]
if not s.startswith("# "):
    print("ac1 RED: the snapshot line is not a '#' comment - tool output is never decorated any other way"); raise SystemExit(1)
fail = []
for needle, why in [
    ("advisory", "the line must name the npm advisory DB as the thing that drifts"),
    ("advisory-DB-dependent", "the line must state that the count is advisory-DB-dependent"),
    ("fresh", "the line must state that the fence measures report-vs-fresh-regen freshness"),
]:
    if needle not in s:
        fail.append("snapshot line lacks %r - %s" % (needle, why))
if re.search(r"\d{4}-\d{2}-\d{2}", s) is None:
    fail.append("the snapshot line carries no YYYY-MM-DD date - an undated snapshot is not attributable")
if re.search(r"[0-9]+ vulnerabilit", s):
    fail.append("the snapshot line itself carries a '<n> vulnerabilit' phrase - it would be parsed as a count by the head-1/tail-1 regexes and double-count the baseline")
for frag in ("23", "14"):
    if re.search(r"(^|[^0-9])" + frag + r" vulnerabilit", s):
        fail.append("the snapshot line hardcodes count %s - the disclosure must be count-free so it cannot go stale twice" % frag)
if fail:
    sys.stdout.write("ac1 evidence: " + "; ".join(fail) + "\n")
    print("ac1 RED: the dated-snapshot disclosure is not honest (%d defects above)" % len(fail))
    raise SystemExit(1)
counts = re.findall(r"([0-9]+) vulnerabilit", t)
if not counts:
    print("ac1 RED: no '<n> vulnerabilit' summary line parses from the report"); raise SystemExit(1)
sys.stdout.write("ac1 evidence: report leads with the tool line; dated snapshot line (count-free, dated %s) present once; parsed summary counts=%s\n" % (re.findall(r"\d{4}-\d{2}-\d{2}", s)[:1], counts))
PYEOF
G=$(wslpath -w "$PWD")
for p in package.json frontend/package.json backend/pyproject.toml backend/uv.lock e2e/package.json; do
  a=$(cmd.exe /c "git -C $G rev-parse HEAD:$p" 2>/dev/null | tr -d "\r")
  b=$(cmd.exe /c "git -C $G hash-object $p" 2>/dev/null | tr -d "\r")
  [ -n "$a" ] || { echo "ac1 RED: manifest blob unreadable: $p"; exit 1; }
  [ "$a" = "$b" ] || { echo "ac1 RED: manifest changed: $p - the re-baseline may move the report, never a dependency manifest"; exit 1; }
done
echo "ac1 evidence: five manifests byte-untouched (read-only audit proof, the same set leg 165 checks)"
t=$(mktemp /tmp/t125-ac1-XXXXXX.txt)
NPM_AUDIT_REPORT="$t" make security-npm-audit >/dev/null 2>&1 || { rm -f "$t"; echo "ac1 RED: make security-npm-audit (read-only override path) failed"; exit 1; }
n=$(grep -oE "[0-9]+ vulnerabilit" "$R" | grep -oE "^[0-9]+" | tail -1)
n2=$(grep -oE "[0-9]+ vulnerabilit" "$t" | grep -oE "^[0-9]+" | tail -1)
rm -f "$t"
[ "${n2:-x}" = "$n" ] || { echo "ac1 RED: committed count=$n but a fresh regeneration says $n2 - the report is stale or hand-edited (this is exactly the leg-165 premise; the fence is preserved, not loosened)"; exit 1; }
echo "ac1 GREEN: report is fresh-regenerated through the read-only make path, carries the count-free dated-snapshot disclosure, and the five manifests are byte-untouched"
